    "difficulty": 5,
    "stem": "A 59-year-old female attends the urgent and emergency care clinical floor at a regional UK trauma network hospital with clinical findings indicative of MRCEM Toxicology Severe Hypothermia Core Temperature < 28 C Cardiopulmonary Bypass or ECMO Rewarming. Clinical examination and investigative review confirm initiating extracorporeal life support (ECLS/ECMO) rewarming for cardiac arrest or refractory hemodynamic collapse from hypothermia. Vital signs demonstrate blood pressure 120/78 mm Hg, heart rate 76/min, respiratory rate 16/min, and oxygen saturation 98%. Which of the following clinical actions best aligns with RCEM and Resuscitation Council UK guidelines?",
